import React, { useState, useMemo } from "react";
import "../styles/SkinAnalyzer.css";
import { onSkinAnalyze } from "../api/onSkinAnalyze";
import { onProductRecommend } from "../api/onProductRecommend";

export default function SkinAnalyzer() {
  const [photo, setPhoto] = useState(null);
  const [photoPreview, setPhotoPreview] = useState(null);
  const [analysis, setAnalysis] = useState(null);
  const [recommendations, setRecommendations] = useState("");
  const [loading, setLoading] = useState(false);
  const [loadingRec, setLoadingRec] = useState(false);

  // 📌 Загрузка фото
  const handlePhotoChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setPhoto(file);

    const reader = new FileReader();
    reader.onloadend = () => setPhotoPreview(reader.result);
    reader.readAsDataURL(file);
  };

  // 📌 useMemo — кэш анализа
  const memoizedAnalysis = useMemo(() => analysis, [analysis]);

  // 📌 Анализ кожи
  const handleAnalyze = () => {
    if (!photo) {
      alert("Загрузите фото");
      return;
    }

    setLoading(true);
    setAnalysis(null);
    setRecommendations("");

    onSkinAnalyze(photo)
      .then((data) => setAnalysis(data))
      .catch(() => alert("Ошибка анализа кожи"))
      .finally(() => setLoading(false));
  };

  // 📌 Рекомендации
  const handleRecommendations = () => {
    if (!memoizedAnalysis) {
      alert("Сначала выполните анализ");
      return;
    }

    setLoadingRec(true);

    onProductRecommend(memoizedAnalysis)
      .then((data) => setRecommendations(data))
      .catch(() => alert("Ошибка рекомендаций"))
      .finally(() => setLoadingRec(false));
  };

  return (
    <div className="skin-analyzer">
      <div className="container">
        <h2 className="title">🧬 Анализ кожи</h2>

        {/* ===== ЗАГРУЗКА ФОТО ===== */}
        <div className="upload-section">
          <div className="file-input-container">
            <label className="file-input-label">
              <input
                type="file"
                accept="image/*"
                onChange={handlePhotoChange}
                className="file-input"
              />
              <span className="upload-button">📸 Выбрать фото</span>
            </label>

            {photo && <span className="file-name">{photo.name}</span>}
          </div>

          {photoPreview && (
            <div className="photo-preview">
              <img src={photoPreview} alt="Предпросмотр" />
            </div>
          )}

          <button
            className="analyze-button"
            onClick={handleAnalyze}
            disabled={loading}
          >
            {loading ? (
              <>
                <span className="spinner" /> Анализ...
              </>
            ) : (
              "🔍 Анализировать кожу"
            )}
          </button>
        </div>

        {/* ===== РЕЗУЛЬТАТЫ АНАЛИЗА ===== */}
        {memoizedAnalysis && (
          <div className="results-section">
            <h3 className="section-title">📊 Результаты анализа</h3>

            <div className="analysis-grid">
              {Object.entries(memoizedAnalysis).map(
                ([key, value], index) => (
                  <div key={index} className="analysis-item">
                    <div className="analysis-header">
                      <span className="item-index">{index + 1}</span>
                      <span className="item-name">{key}</span>
                    </div>

                    <div className="item-level">
                      Вероятность: {value}%
                    </div>
                  </div>
                )
              )}
            </div>

            <button
              className="recommend-button"
              onClick={handleRecommendations}
              disabled={loadingRec}
            >
              {loadingRec ? (
                <>
                  <span className="spinner" /> Генерация...
                </>
              ) : (
                "💡 Получить рекомендации"
              )}
            </button>
          </div>
        )}

        {/* ===== РЕКОМЕНДАЦИИ ===== */}
        {recommendations && (
          <div className="recommendations-section">
            <div className="recommendations-card">
              <div className="recommendations-content">
                <div className="recommendation-paragraph intro">
                  {recommendations}
                </div>
              </div>

              <div className="recommendations-footer">
                <div className="tip">
                  💡 Рекомендации носят информационный характер
                </div>

                <button
                  className="save-button"
                  onClick={() =>
                    navigator.clipboard.writeText(recommendations)
                  }
                >
                  📋 Скопировать рекомендации
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
